                        params={'access_key': API_KEY},
                        timeout=5
                    )
                    if geo_response.status_code == 200:
                        geo_data = geo_response.json()
                        result[domain] = geo_data
                    else:
                        result[domain] = None
                else:
                    result[domain] = None
            else:
                result[domain] = None
