SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
class PostRequestHandler(http.server.BaseHTTPRequestHandler):
    """HTTP request handler for processing POST requests with JSON data."""

    def _send_response(self, status_code: int, content: Dict[str, Any]) -> None:
        """Send HTTP response with JSON content."""
        response_body = json.dumps(content).encode('utf-8')

        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response_body)))
        self.end_headers()
        self.wfile.write(response_body)

    def _parse_json_body(self) -> Dict[str, Any]:
        """Parse JSON from request body."""
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length == 0:
            return {}

        raw_data = self.rfile.read(content_length)
        try:
            return json.loads(raw_data.decode('utf-8'))
        except json.JSONDecodeError:
            return None

    def do_POST(self) -> None:
        """Handle POST requests."""
        # Check Content-Type header
        content_type = self.headers.get('Content-Type', '')
        if not content_type.startswith('application/json'):
            self._send_response(
                HTTPStatus.BAD_REQUEST,
                {'status': 'error', 'message': 'Content-Type header is not application/json'}
            )
            return

        # Parse JSON body
        parsed_data = self._parse_json_body()
        if parsed_data is None:
            self._send_response(
                HTTPStatus.BAD_REQUEST,
                {'status': 'error', 'message': 'Invalid JSON'}
            )
            return

        # Check for 'data' key
        if 'data' not in parsed_data:
            self._send_response(
                HTTPStatus.BAD_REQUEST,
                {'status': 'error', 'message': 'No data key in request'}
            )
            return

        # Success response
        self._send_response(HTTPStatus.OK, SUCCESS_RESPONSE)

    def log_message(self, format: str, *args: Any) -> None:
        """Override to suppress default logging."""
        pass
def task_func(port: int = 8000) -> socketserver.TCPServer:
    """
    Creates and returns an HTTP server with POST request handler.

    Parameters:
    - port (int): The port number to run the server on (default: 8000)

    Returns:
    - socketserver.TCPServer: The HTTP server instance

    Example:
    >>> server = task_func(8080)
    >>> # Server runs on port 8080
    >>> # Send POST request with JSON: {"data": "some value"}
    >>> # Server responds with: {"status": "success", "message": "Data received successfully."}
