import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.

    Parameters:
    API_URL (str): The URL of the API that returns the public IP address.

    Returns:
    str: The public IP address.

    Raises:
    Exception: If the API request fails, raises an exception with the error message.
    """
    try:
        # Make the API request
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            data = response.read().decode('utf-8')

            # Try to parse as JSON first
            try:
                json_data = json.loads(data)
                # Look for IP address in JSON structure
                if isinstance(json_data, dict):
                    # Check common JSON response formats
                    for key in ['ip', 'IP', 'address', 'query']:
                        if key in json_data:
                            ip = str(json_data[key])
                            if re.fullmatch(IP_REGEX, ip):
                                return ip

                # If no IP found in common keys, search all string values
                if isinstance(json_data, dict):
                    for value in json_data.values():
                        if isinstance(value, str) and re.fullmatch(IP_REGEX, value):
                            return value
            except json.JSONDecodeError:
                # If not JSON, search for IP pattern in plain text
                pass

            # Search for IP address pattern in the response
            match = re.search(IP_REGEX, data)
            if match:
                return match.group(0)
            else:
                raise Exception(f"No valid IP address found in API response: {data[:100]}...")

    except urllib.error.URLError as e:
        raise Exception(f"Failed to connect to API: {str(e)}")
    except urllib.error.HTTPError as e:
        raise Exception(f"HTTP error {e.code}: {e.reason}")
    except Exception as e:
        raise Exception(f"Error getting IP address: {str(e)}")

